import React, { useState, useMemo, useEffect } from 'react';

// --- Helper Icon Components ---
const EditIcon = () => ( <svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" style={{ cursor: 'pointer', color: '#6c757d' }}><path d="M11 4H4a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2v-7" /><path d="M18.5 2.5a2.121 2.121 0 0 1 3 3L12 15l-4 1 1-4 9.5-9.5z" /></svg> );
const DeleteIcon = () => ( <svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" style={{ cursor: 'pointer', color: '#dc3545' }}><polyline points="3 6 5 6 21 6" /><path d="M19 6v14a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V6m3 0V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2" /></svg> );
const InfoIcon = () => ( <svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" style={{ color: '#6c757d', marginLeft: '8px' }}><circle cx="12" cy="12" r="10" /><line x1="12" y1="16" x2="12" y2="12" /><line x1="12" y1="8" x2="12.01" y2="8" /></svg> );
const SaveIcon = () => ( <svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" style={{ cursor: 'pointer', color: '#28a745' }}><path d="M19 21H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h11l5 5v11a2 2 0 0 1-2 2z" /><polyline points="17 21 17 13 7 13 7 21" /><polyline points="7 3 7 8 15 8" /></svg> );
const CancelIcon = () => ( <svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" style={{ cursor: 'pointer', color: '#6c757d' }}><circle cx="12" cy="12" r="10" /><line x1="15" y1="9" x2="9" y2="15" /><line x1="9" y1="9" x2="15" y2="15" /></svg> );

// --- Main Per-delivery Allocation Tab Component ---
export default function PerDeliveryAllocationTab({ term, onAllocationChange }) {
    // --- State Management ---
    const [firstOfferingOfYear, setFirstOfferingOfYear] = useState('Yes');
    const [deliveries, setDeliveries] = useState([
        { id: 1, deliveryLocation: 'CTN', lecturer: 'Mary', weeklyLectureTime: 2, earlyCareerLoading: 'No' },
        { id: 2, deliveryLocation: 'PEN', lecturer: 'Mary', weeklyLectureTime: 0, earlyCareerLoading: 'No' },
        { id: 3, deliveryLocation: 'KWD', lecturer: 'Mary', weeklyLectureTime: 0, earlyCareerLoading: 'No' },
    ]);

    // --- Edit Mode State ---
    const [editingRowId, setEditingRowId] = useState(null);
    const [originalRowData, setOriginalRowData] = useState(null);

    // --- Notification State ---
    const [notification, setNotification] = useState({ message: '', type: '' });

    // --- Show a notification and automatically hide it ---
    const showNotification = (message, type = 'success') => {
        setNotification({ message, type });
        setTimeout(() => {
            setNotification({ message: '', type: '' });
        }, 3000);
    };

    // --- Calculation Logic (no changes here) ---
    const calculatedData = useMemo(() => {
        const termMultiplier = 1.0;
        const getEarlyCareerBonus = (loadingType) => ({ "Yes - materials provided": 0.02, "Yes - materials need major rewriting": 0.03, "Yes - no materials provided": 0.04 }[loadingType] || 0);
        const individualAllocations = deliveries.map(d => 0.01 + (Number(d.weeklyLectureTime) * termMultiplier * 0.01) + getEarlyCareerBonus(d.earlyCareerLoading));
        const sumOfIndividualAllocations = individualAllocations.reduce((sum, alloc) => sum + alloc, 0);
        let firstOfferingBonus = 0;
        if (firstOfferingOfYear === 'Yes' && deliveries.length > 0) {
            const maxLectureTime = Math.max(...deliveries.map(d => Number(d.weeklyLectureTime) || 0));
            firstOfferingBonus = 0.01 * termMultiplier * maxLectureTime;
        }
        const totalPerDeliveryAllocation = sumOfIndividualAllocations + firstOfferingBonus;
        return { total: totalPerDeliveryAllocation, individuals: individualAllocations };
    }, [deliveries, firstOfferingOfYear, term]);

    // --- Effect to notify parent of allocation changes ---
    useEffect(() => {
        if (onAllocationChange) onAllocationChange(calculatedData.total);
    }, [calculatedData.total, onAllocationChange]);

    // --- Event Handlers ---
    const handleAddDelivery = () => {
        const newId = deliveries.length > 0 ? Math.max(...deliveries.map(d => d.id)) + 1 : 1;
        const newRow = { id: newId, deliveryLocation: '', lecturer: '', weeklyLectureTime: 0, earlyCareerLoading: 'No' };
        setDeliveries([...deliveries, newRow]);
        setEditingRowId(newId); // Immediately enter edit mode for the new row
        setOriginalRowData(newRow);
    };

    const handleDeleteDelivery = (idToDelete) => {
        setDeliveries(deliveries.filter(d => d.id !== idToDelete));
        showNotification('Record deleted successfully!', 'success');
    };

    const handleDeliveryChange = (id, field, value) => {
        setDeliveries(deliveries.map(d => d.id === id ? { ...d, [field]: value } : d));
    };

    // --- Edit Mode Handlers ---
    const handleEdit = (row) => {
        setEditingRowId(row.id);
        setOriginalRowData(row); // Save original data for cancel
    };

    const handleSave = (id) => {
        setEditingRowId(null);
        setOriginalRowData(null);
        showNotification('Record saved successfully!', 'success');
    };

    const handleCancel = (id) => {
        // Restore original data
        setDeliveries(deliveries.map(d => d.id === id ? originalRowData : d));
        setEditingRowId(null);
        setOriginalRowData(null);
    };

    const earlyCareerOptions = ["No", "Yes - materials provided", "Yes - materials need major rewriting", "Yes - no materials provided"];

    return (
        <div style={styles.container}>
            {/* --- Notification Banner --- */}
            {notification.message && (
                <div style={{...styles.notification, ...(notification.type === 'success' ? styles.notificationSuccess : {})}}>
                    {notification.message}
                </div>
            )}

            <div style={styles.formGroup}>
                <label style={styles.label} htmlFor="totalAllocation" title="This is the total calculated per-delivery allocation for all listed deliveries.">
                    Per-delivery Allocation <InfoIcon />
                </label>
                <input type="text" id="totalAllocation" readOnly style={styles.totalInput} value={`${(calculatedData.total * 100).toFixed(1)}%`} />
            </div>

            <div style={styles.formGroupWithBorder}>
                <label style={styles.label} htmlFor="firstOffering">First offering of the calendar year</label>
                <select id="firstOffering" style={styles.select} value={firstOfferingOfYear} onChange={(e) => setFirstOfferingOfYear(e.target.value)}>
                    <option value="Yes">Yes</option>
                    <option value="No">No</option>
                </select>
            </div>

            <div style={styles.tableActions}>
                 <button style={styles.addButton} onClick={handleAddDelivery}>+ Add</button>
            </div>

            <div style={styles.tableContainer}>
                <div style={styles.tableHeader}>
                    <div style={{...styles.tableCell, flex: 0.7}}>Actions</div>
                    <div style={{...styles.tableCell, flex: 1}}>Delivery</div>
                    <div style={{...styles.tableCell, flex: 2}}>Lecturer / Campus Coordinator</div>
                    <div style={{...styles.tableCell, flex: 2}}>Weekly lecture time (hours)</div>
                    <div style={{...styles.tableCell, flex: 2.5}}>Early career academic loading</div>
                    <div style={{...styles.tableCell, flex: 1, justifyContent: 'flex-end'}}>Allocation</div>
                </div>

                {deliveries.map((delivery, index) => {
                    const isEditing = editingRowId === delivery.id; // Check if the current row is in edit mode
                    return (
                        <div key={delivery.id} style={styles.tableRow}>
                            {/* --- Conditional rendering for Actions cell --- */}
                            <div style={{...styles.tableCell, flex: 0.7, display: 'flex', gap: '12px' }}>
                                {isEditing ? (
                                    <>
                                        <SaveIcon onClick={() => handleSave(delivery.id)} />
                                        <CancelIcon onClick={() => handleCancel(delivery.id)} />
                                    </>
                                ) : (
                                    <>
                                        <EditIcon onClick={() => handleEdit(delivery)} />
                                        <DeleteIcon onClick={() => handleDeleteDelivery(delivery.id)} />
                                    </>
                                )}
                            </div>

                            {/* --- Conditional rendering for data cells --- */}
                            <div style={{...styles.tableCell, flex: 1}}>{isEditing ? <input type="text" style={styles.tableInput} value={delivery.deliveryLocation} onChange={(e) => handleDeliveryChange(delivery.id, 'deliveryLocation', e.target.value)} /> : <span style={styles.readOnlyText}>{delivery.deliveryLocation}</span>}</div>
                            <div style={{...styles.tableCell, flex: 2}}>{isEditing ? <input type="text" style={styles.tableInput} value={delivery.lecturer} onChange={(e) => handleDeliveryChange(delivery.id, 'lecturer', e.target.value)} /> : <span style={styles.readOnlyText}>{delivery.lecturer}</span>}</div>
                            <div style={{...styles.tableCell, flex: 2}}>{isEditing ? <input type="number" style={styles.tableInput} value={delivery.weeklyLectureTime} min="0" onChange={(e) => handleDeliveryChange(delivery.id, 'weeklyLectureTime', e.target.value)} /> : <span style={styles.readOnlyText}>{delivery.weeklyLectureTime}</span>}</div>
                            <div style={{...styles.tableCell, flex: 2.5}}>{isEditing ? <select style={styles.tableSelect} value={delivery.earlyCareerLoading} onChange={(e) => handleDeliveryChange(delivery.id, 'earlyCareerLoading', e.target.value)} >{earlyCareerOptions.map(opt => <option key={opt} value={opt}>{opt}</option>)}</select> : <span style={styles.readOnlyText}>{delivery.earlyCareerLoading}</span>}</div>
                            <div style={{...styles.tableCell, flex: 1, justifyContent: 'flex-end'}}><span style={{...styles.readOnlyText, ...styles.allocationText}}>{(calculatedData.individuals[index] * 100).toFixed(1)}%</span></div>
                        </div>
                    );
                })}
            </div>

            <div style={styles.footer}>
                <button style={styles.saveButton}>Save</button>
            </div>
        </div>
    );
}


